# 中文注释版 / Annotated source — VetBLCM 0.1.10
# 双语前端布局与输入控件；不在布局层拟合模型。
# 本次仅增加说明；统计行为与已验证的 0.1.10 相同。

# 建立双语显示节点，使用同一个界面结构切换中文/英文。
ui_text <- function(zh,en) shiny::tagList(shiny::tags$span(class="lang-zh",zh),shiny::tags$span(class="lang-en",en))
# 用于可见的简短界面说明，不承载统计计算。
ui_note <- function(zh,en) shiny::div(class="note",ui_text(zh,en))
# 把较长说明放到可悬停或聚焦查看的帮助提示，避免与真实错误提示混淆。
ui_help <- function(zh,en) shiny::span(class="help-tip",tabindex="0",title="帮助 / Help",shiny::tags$span(class="help-tip-icon","?"),shiny::tags$span(class="help-tip-content",ui_text(zh,en)))
# 建立向导页的容器与标题；页面顺序由应用定义。
ui_page <- function(id,zh,en,...) shiny::conditionalPanel(paste0("input.page == '",id,"'"),shiny::div(class="page-card",shiny::h2(ui_text(zh,en)),...))
